                    System.out.println("잔고: " + balance);
                    break;

                case "4":                     // 4. 프로그램 종료
                    run = false;              // 루프 종료
                    break;

                default:                      // 입력값이 none of the above
                    System.out.println("1, 2, 3, 4 중 하나로 입력하시오.");
